:host {
  display: block;
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.users-table {
  width: 100%;
  min-width: 900px;

  border: 1px solid var(--color-border);
  border-collapse: separate;
  border-spacing: 0;

  background: var(--color-surface);
  box-shadow: var(--shadow-sm);

  overflow: hidden;

  font-family:
    Inter,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  font-size: 14px;
  line-height: 1.4;
  color: var(--color-text);

  // ===========================================================================
  // Row
  // ===========================================================================

  &__row {
    transition: background-color 0.15s ease;

    &:hover {
      background: var(--color-surface-hover);
    }

    &:last-child {
      .users-table__cell {
        border-bottom: 0;
      }
    }
  }

  // ===========================================================================
  // Cell
  // ===========================================================================

  &__cell {
    padding: 14px 16px;

    border-bottom: 1px solid var(--color-border-subtle);

    vertical-align: middle;
    white-space: nowrap;

    &:first-child {
      font-weight: 500;
      color: var(--color-text);
    }

    &:last-child {
      width: 1%;
      padding-right: 12px;
    }
  }
}

// =============================================================================
// Actions
// =============================================================================

.actions {
  &__buttons {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 6px;
  }

  &__button {
    min-height: 32px;
    padding: 6px 11px;

    border: 1px solid var(--color-border);
    border-radius: 6px;

    background: var(--color-surface);

    color: var(--color-text-secondary);

    font: inherit;
    font-size: 13px;
    font-weight: 500;
    line-height: 1;

    white-space: nowrap;

    cursor: pointer;

    transition:
      background-color 0.15s ease,
      border-color 0.15s ease,
      color 0.15s ease,
      box-shadow 0.15s ease,
      transform 0.1s ease;

    &:focus-visible {
      outline: 2px solid var(--color-focus);
      outline-offset: 2px;
    }

    &:active {
      transform: translateY(1px);
    }

    // Select
    &--select {
      color: var(--color-accent);
      border-color: var(--color-accent);

      &:hover {
        color: var(--color-text-on-accent);
        background: var(--color-accent);
        border-color: var(--color-accent);
      }

      &:active {
        background: var(--color-accent-active);
        border-color: var(--color-accent-active);
      }
    }

    // Edit
    &--edit {
      color: var(--color-info);

      &:hover {
        background: var(--color-info-soft);
        border-color: var(--color-info);
      }

      &:active {
        background: var(--color-surface-active);
      }
    }

    // Remove
    &--remove {
      color: var(--color-danger);

      &:hover {
        background: var(--color-danger-soft);
        border-color: var(--color-danger);
      }

      &:active {
        background: var(--color-danger-soft);
      }
    }
  }
}

// =============================================================================
// Tablet / Mobile
// =============================================================================

@media (max-width: 768px) {
  :host {
    overflow-x: visible;
  }

  .users-table {
    width: 100%;
    min-width: 0;
      background: var(--color-surface);

    display: block;

    border: 0;
    border-radius: 0;

    box-shadow: none;

    // -------------------------------------------------------------------------
    // Card
    // -------------------------------------------------------------------------

    &__row {
      display: block;

      width: calc(100% - 2rem);
      margin: 1rem;


      border: 1px solid var(--color-border);

      background: var(--color-surface);
      box-shadow: var(--shadow-sm);

      overflow: hidden;

      &:hover {
        background: var(--color-surface);
      }

      &:last-child {
        margin-bottom: 0;
      }
    }

    // -------------------------------------------------------------------------
    // Cell
    // -------------------------------------------------------------------------

    &__cell {
      display: flex;
      align-items: center;
      justify-content: space-between;

      width: 100%;
      min-width: 0;

      gap: 20px;

      padding: 12px 14px;

      border-bottom: 1px solid var(--color-border-subtle);

      white-space: normal;
      text-align: right;

      overflow-wrap: anywhere;

      &::before {
        content: attr(data-label);

        flex: 0 0 auto;

        color: var(--color-text-secondary);

        font-size: 12px;
        font-weight: 600;
        line-height: 1.3;
        letter-spacing: 0.01em;

        text-align: left;
      }

      // IMPORTANT:
      // Override the desktop `width: 1%` rule.
      &:last-child {
        width: 100%;
        padding-right: 14px;

        border-bottom: 0;
      }
    }
  }

  // ===========================================================================
  // Mobile actions
  // ===========================================================================

  .actions {
    &__buttons {
      display: flex;
      align-items: center;
      justify-content: flex-end;

      width: 100%;

      gap: 6px;
    }

    &__button {
      flex: 0 0 auto;

      min-width: max-content;
      min-height: 34px;

      padding: 7px 12px;

      white-space: nowrap;
    }
  }
}

// =============================================================================
// Small mobile
// =============================================================================

@media (max-width: 480px) {
  .users-table {
    &__cell {
      align-items: flex-start;
      flex-direction: column;

      gap: 4px;

      text-align: left;

      &::before {
        font-size: 11px;
        line-height: 1.2;
        text-transform: uppercase;
        letter-spacing: 0.05em;
      }

      // Actions cell
      &:last-child {
        align-items: stretch;

        // Keep the cell full width!
        width: 100%;

        &::before {
          margin-bottom: 4px;
        }
      }
    }
  }

  .actions {
    &__buttons {
      width: 100%;

      display: grid;
      grid-template-columns: repeat(3, 1fr);

      gap: 6px;
    }

    &__button {
      width: 100%;
      min-width: 0;

      padding: 8px 6px;

      white-space: nowrap;
      text-align: center;
    }
  }
}

